// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value) public {
        vm.assume(_value <= address(this).balance);
        vm.deal(address(c), _value);
        ExpensiveRecipient recipient = new ExpensiveRecipient();
        bool ok;
        try c.sendMoney(address(recipient), _value) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
contract ExpensiveRecipient {
    uint256[10] storageBlob;
    fallback() external payable {
        for (uint i = 0; i < storageBlob.length; i++) {
            storageBlob[i] = i;
        }
    }
}
